-- Synthetic legacy database for Rust migration regression tests.
BEGIN TRANSACTION;
CREATE TABLE article_revisions (id INTEGER PRIMARY KEY AUTOINCREMENT, article_id INTEGER NOT NULL, title TEXT NOT NULL, content TEXT NOT NULL, format TEXT NOT NULL, tags TEXT NOT NULL, draft INTEGER NOT NULL, images TEXT NOT NULL, updated_at TEXT NOT NULL, saved_at TEXT NOT NULL);
CREATE TABLE articles (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, content TEXT NOT NULL, format TEXT NOT NULL DEFAULT 'md', images TEXT NOT NULL DEFAULT '[]', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, tags TEXT NOT NULL DEFAULT '', draft INTEGER NOT NULL DEFAULT 0);

正文 & 中文
第二行','md','[]','2026-02-01T12:00:00+08:00','2026-02-01T12:00:00+08:00','测试,猫',0);
CREATE TABLE comments (id INTEGER PRIMARY KEY AUTOINCREMENT, kind TEXT NOT NULL, target_id INTEGER NOT NULL, author TEXT NOT NULL, email TEXT NOT NULL DEFAULT '', site TEXT NOT NULL DEFAULT '', content TEXT NOT NULL, created_at TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'approved', reply_to INTEGER, ip_hash TEXT NOT NULL DEFAULT '');
CREATE TABLE plugin_tombstones (key TEXT NOT NULL, plugin TEXT NOT NULL, deleted_at TEXT NOT NULL, PRIMARY KEY (plugin, key));
CREATE TABLE post_likes (post_id INTEGER NOT NULL, token TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY (post_id, token));
CREATE TABLE posts (id INTEGER PRIMARY KEY AUTOINCREMENT, content TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, pinned INTEGER NOT NULL DEFAULT 0, images TEXT NOT NULL DEFAULT '[]', meta TEXT NOT NULL DEFAULT '', source TEXT NOT NULL DEFAULT '', source_key TEXT NOT NULL DEFAULT '', link TEXT NOT NULL DEFAULT '');
CREATE TABLE rss_feeds (id TEXT PRIMARY KEY, url TEXT NOT NULL, title TEXT NOT NULL DEFAULT '', alias TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, last_sync INTEGER NOT NULL DEFAULT 0, last_error TEXT NOT NULL DEFAULT '', icon TEXT NOT NULL DEFAULT '');
CREATE TABLE schema_versions (component TEXT PRIMARY KEY, version INTEGER NOT NULL);
CREATE TABLE settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE users (id INTEGER PRIMARY KEY, name TEXT NOT NULL, password TEXT NOT NULL);
CREATE TABLE wallpapers (id TEXT PRIMARY KEY, path TEXT NOT NULL, name TEXT NOT NULL, width INTEGER NOT NULL, height INTEGER NOT NULL, bytes INTEGER NOT NULL, mtime INTEGER NOT NULL, post_id INTEGER);
CREATE INDEX idx_comments_target ON comments (kind, target_id, status, created_at);
CREATE INDEX idx_posts_timeline ON posts (created_at DESC, id DESC);
CREATE INDEX idx_posts_pinned_timeline ON posts (pinned DESC, created_at DESC, id DESC);
CREATE INDEX idx_articles_timeline ON articles (draft, created_at DESC, id DESC);
CREATE INDEX idx_article_revisions ON article_revisions (article_id, id DESC);
DELETE FROM "sqlite_sequence";
COMMIT;
